  text: string;
};

type ServerEvent =
  | { type: "message.created"; id: string; seq: number; text: string }
  | { type: "message.typing"; userId: string };

function onSend(text: string) {
  const clientId = crypto.randomUUID();
  messages.push({ key: clientId, text, state: "pending" });
  socket.send(JSON.stringify({ type: "message.send", conversationId, text }));
  render();
}

function onEvent(event: ServerEvent) {
  if (event.type === "message.created") {
    messages.push({ key: event.id, text: event.text, state: "sent" });
    render();
  }
}

